('topic-viii-chem-matter', 'CISCE', NULL, 'VIII', 'Chemistry', 'Matter', 'Matter', 'Use kinetic molecular theory to explain states and changes of state, and apply the law of conservation of mass.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-matter', 'topic-viii-chem-matter', 'Matter', 'Matter is anything that has mass and occupies space. The kinetic molecular theory explains matter as tiny particles in constant motion. Solid particles are closely packed and mainly vibrate about fixed positions; liquid particles remain close but can slide past one another; gas particles are far apart and move freely. Heating raises average kinetic energy, weakens the effect of attraction and can cause melting or vaporisation, while cooling reverses these changes. During particle collisions, energy may be transferred without creating or destroying matter. The law of conservation of mass states that total mass remains unchanged in a physical or chemical change when every reactant, product and participating atmospheric gas is included. A reaction in a closed vessel demonstrates this clearly because no material can enter or escape.', '["Particles of matter are in continuous motion, and their average kinetic energy rises when temperature rises.","Solids have the least inter-particle space and strongest effective attraction; gases have the greatest space and weakest attraction.","Changes of state alter particle arrangement and energy but do not change the chemical identity of a pure substance.","In a closed system, total mass of reactants equals total mass of products, including any gas that participates in the reaction."]', '{"prompt":"A sealed flask contains 20.8 g of barium chloride solution and a small tube containing 14.2 g of sodium sulphate solution. The solutions are mixed without opening the flask. What mass should the flask contents have after the reaction?","steps":["Add the masses present before mixing: 20.8 g + 14.2 g = 35.0 g.","The reaction forms a precipitate, but the flask remains closed and no matter enters or leaves.","By conservation of mass, the contents still have a total mass of 35.0 g."],"answer":"35.0 g"}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-matter-q1', 'topic-viii-chem-matter', 'single_choice', 'Which statement correctly describes Matter?', '[{"id":"a","label":"Particles of matter are in continuous motion, and their average kinetic energy rises when temperature rises."},{"id":"b","label":"A physical change preserves chemical composition even when state, size, shape or appearance changes."},{"id":"c","label":"A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds."},{"id":"d","label":"Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction."}]', '{"choice":"a"}', 'Particles of matter are in continuous motion, and their average kinetic energy rises when temperature rises.', 1, 0, 'reviewed', 1),
('viii-chem-matter-q2', 'topic-viii-chem-matter', 'single_choice', 'Which statement correctly describes Matter?', '[{"id":"a","label":"Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes."},{"id":"b","label":"Solids have the least inter-particle space and strongest effective attraction; gases have the greatest space and weakest attraction."},{"id":"c","label":"Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions."},{"id":"d","label":"Mixtures have variable composition and usually retain the properties of their components."}]', '{"choice":"b"}', 'Solids have the least inter-particle space and strongest effective attraction; gases have the greatest space and weakest attraction.', 2, 0, 'reviewed', 1),
('viii-chem-matter-q3', 'topic-viii-chem-matter', 'single_choice', 'Which statement correctly describes Matter?', '[{"id":"a","label":"A separation technique is selected from differences in solubility, particle size, density, magnetism, sublimation or boiling point."},{"id":"b","label":"Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."},{"id":"c","label":"Changes of state alter particle arrangement and energy but do not change the chemical identity of a pure substance."},{"id":"d","label":"Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons."}]', '{"choice":"c"}', 'Changes of state alter particle arrangement and energy but do not change the chemical identity of a pure substance.', 3, 0, 'reviewed', 1),
('viii-chem-matter-q4', 'topic-viii-chem-matter', 'single_choice', 'Which statement correctly describes Matter?', '[{"id":"a","label":"Electrons occupy shells, and the outermost-shell electrons are called valence electrons."},{"id":"b","label":"Isotopes have the same atomic number but different mass numbers because their neutron counts differ."},{"id":"c","label":"Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."},{"id":"d","label":"In a closed system, total mass of reactants equals total mass of products, including any gas that participates in the reaction."}]', '{"choice":"d"}', 'In a closed system, total mass of reactants equals total mass of products, including any gas that participates in the reaction.', 4, 0, 'reviewed', 1),
('viii-chem-matter-q5', 'topic-viii-chem-matter', 'single_choice', 'A sealed flask contains 20.8 g of barium chloride solution and a small tube containing 14.2 g of sodium sulphate solution. The solutions are mixed without opening the flask. What mass should the flask contents have after the reaction? Which conclusion is correct?', '[{"id":"a","label":"35.0 g"},{"id":"b","label":"Melting is physical; burning is chemical."},{"id":"c","label":"Magnetic separation, then sublimation, leaving sand."},{"id":"d","label":"17 protons, 17 electrons, 20 neutrons; 2,8,7."}]', '{"choice":"a"}', 'Add the masses present before mixing: 20.8 g + 14.2 g = 35.0 g. The reaction forms a precipitate, but the flask remains closed and no matter enters or leaves. By conservation of mass, the contents still have a total mass of 35.0 g.', 2, 1, 'reviewed', 1);
