VALUES
('topic-viii-chem-physical-chemical-changes', 'CISCE', NULL, 'VIII', 'Chemistry', 'Changes in Matter', 'Physical and Chemical Changes', 'Distinguish physical and chemical changes using observable evidence, reversibility and formation of new substances.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-physical-chemical-changes', 'topic-viii-chem-physical-chemical-changes', 'Physical and Chemical Changes', 'Changes around us may be slow or fast, reversible or irreversible, periodic or non-periodic. A physical change alters state, size or shape without producing a substance with a new chemical composition; melting ice, dissolving sugar and stretching a spring are examples. A chemical change rearranges atoms to form one or more new substances with properties different from the starting materials. Useful evidence includes a lasting colour change, gas evolution, precipitate formation, light or heat not supplied from outside, or a new odour, although no single observation alone is always conclusive. Rusting, combustion and curdling are chemical changes. Reversibility is a helpful clue but not the definition: some physical changes are difficult to reverse, while some chemical reactions can be reversed under suitable conditions. Classification must therefore focus on whether new substances form.', '["A physical change preserves chemical composition even when state, size, shape or appearance changes.","A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds.","Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction.","Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes."]', '{"prompt":"Classify melting candle wax and burning candle vapour, and justify each classification.","steps":["Melting changes solid wax to liquid wax without changing its composition, so it is physical.","Near the wick, wax vapour reacts with oxygen and forms carbon dioxide and water.","Because burning forms new substances, combustion is chemical even though melting and burning occur together."],"answer":"Melting is physical; burning is chemical."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-physical-chemical-changes-q1', 'topic-viii-chem-physical-chemical-changes', 'single_choice', 'Which statement correctly describes Physical and Chemical Changes?', '[{"id":"a","label":"A physical change preserves chemical composition even when state, size, shape or appearance changes."},{"id":"b","label":"Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."},{"id":"c","label":"Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons."},{"id":"d","label":"Electrons occupy shells, and the outermost-shell electrons are called valence electrons."}]', '{"choice":"a"}', 'A physical change preserves chemical composition even when state, size, shape or appearance changes.', 1, 0, 'reviewed', 1),
('viii-chem-physical-chemical-changes-q2', 'topic-viii-chem-physical-chemical-changes', 'single_choice', 'Which statement correctly describes Physical and Chemical Changes?', '[{"id":"a","label":"Isotopes have the same atomic number but different mass numbers because their neutron counts differ."},{"id":"b","label":"A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds."},{"id":"c","label":"Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."},{"id":"d","label":"Element symbols have a capital first letter; formula subscripts show the simplest whole-number ratio of atoms or ions."}]', '{"choice":"b"}', 'A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds.', 2, 0, 'reviewed', 1),
('viii-chem-physical-chemical-changes-q3', 'topic-viii-chem-physical-chemical-changes', 'single_choice', 'Which statement correctly describes Physical and Chemical Changes?', '[{"id":"a","label":"Valencies or ionic charges must balance to make an electrically neutral compound."},{"id":"b","label":"Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion."},{"id":"c","label":"Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction."},{"id":"d","label":"Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."}]', '{"choice":"c"}', 'Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction.', 3, 0, 'reviewed', 1),
('viii-chem-physical-chemical-changes-q4', 'topic-viii-chem-physical-chemical-changes', 'single_choice', 'Which statement correctly describes Physical and Chemical Changes?', '[{"id":"a","label":"Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change."},{"id":"b","label":"A more reactive element can displace a less reactive element from its compound."},{"id":"c","label":"Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them."},{"id":"d","label":"Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes."}]', '{"choice":"d"}', 'Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes.', 4, 0, 'reviewed', 1),
('viii-chem-physical-chemical-changes-q5', 'topic-viii-chem-physical-chemical-changes', 'single_choice', 'Classify melting candle wax and burning candle vapour, and justify each classification. Which conclusion is correct?', '[{"id":"a","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"b","label":"Melting is physical; burning is chemical."},{"id":"c","label":"162.5 g"},{"id":"d","label":"Risk of carbon monoxide; stop, ventilate and improve the air supply."}]', '{"choice":"b"}', 'Melting changes solid wax to liquid wax without changing its composition, so it is physical. Near the wick, wax vapour reacts with oxygen and forms carbon dioxide and water. Because burning forms new substances, combustion is chemical even though melting and burning occur together.', 2, 1, 'reviewed', 1);
