VALUES
('topic-viii-chem-elements-compounds-mixtures', 'CISCE', NULL, 'VIII', 'Chemistry', 'Classification and Separation', 'Elements, Compounds and Mixtures', 'Classify substances and choose separation methods from differences in physical properties.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-elements-compounds-mixtures', 'topic-viii-chem-elements-compounds-mixtures', 'Elements, Compounds and Mixtures', 'An element contains one kind of atom and cannot be decomposed by ordinary chemical methods. A compound contains atoms of two or more elements chemically combined in a fixed ratio, and its properties differ from those of its elements. A mixture contains substances physically combined in variable proportions; each component largely retains its properties and can be separated physically. Separation depends on a measurable property difference. Filtration separates an insoluble solid from a liquid, evaporation recovers a dissolved solid, crystallisation obtains purer crystals, sublimation separates a volatile solid, a separating funnel handles immiscible liquids, and chromatography separates dissolved substances by unequal movement between phases. Distillation separates a solvent or liquids using different boiling points, while fractional distillation is preferred when boiling points are close. The method must match the mixture rather than being chosen by habit.', '["Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions.","Mixtures have variable composition and usually retain the properties of their components.","A separation technique is selected from differences in solubility, particle size, density, magnetism, sublimation or boiling point.","Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."]', '{"prompt":"Design a sequence to separate iron filings, ammonium chloride and sand from one dry mixture.","steps":["Use a magnet to remove the magnetic iron filings.","Heat the remaining mixture gently under an inverted funnel so ammonium chloride sublimes and deposits on the cool surface.","The non-subliming sand remains in the dish and is collected after cooling."],"answer":"Magnetic separation, then sublimation, leaving sand."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-elements-compounds-mixtures-q1', 'topic-viii-chem-elements-compounds-mixtures', 'single_choice', 'Which statement correctly describes Elements, Compounds and Mixtures?', '[{"id":"a","label":"Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions."},{"id":"b","label":"Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion."},{"id":"c","label":"Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."},{"id":"d","label":"Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change."}]', '{"choice":"a"}', 'Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions.', 1, 0, 'reviewed', 1),
('viii-chem-elements-compounds-mixtures-q2', 'topic-viii-chem-elements-compounds-mixtures', 'single_choice', 'Which statement correctly describes Elements, Compounds and Mixtures?', '[{"id":"a","label":"A more reactive element can displace a less reactive element from its compound."},{"id":"b","label":"Mixtures have variable composition and usually retain the properties of their components."},{"id":"c","label":"Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them."},{"id":"d","label":"A catalyst changes reaction rate while being regenerated, and reaction rate also depends on temperature, concentration and surface area."}]', '{"choice":"b"}', 'Mixtures have variable composition and usually retain the properties of their components.', 2, 0, 'reviewed', 1),
('viii-chem-elements-compounds-mixtures-q3', 'topic-viii-chem-elements-compounds-mixtures', 'single_choice', 'Which statement correctly describes Elements, Compounds and Mixtures?', '[{"id":"a","label":"Laboratory hydrogen is commonly prepared from zinc and a dilute non-oxidising acid and collected over water."},{"id":"b","label":"The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint."},{"id":"c","label":"A separation technique is selected from differences in solubility, particle size, density, magnetism, sublimation or boiling point."},{"id":"d","label":"Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water."}]', '{"choice":"c"}', 'A separation technique is selected from differences in solubility, particle size, density, magnetism, sublimation or boiling point.', 3, 0, 'reviewed', 1),
('viii-chem-elements-compounds-mixtures-q4', 'topic-viii-chem-elements-compounds-mixtures', 'single_choice', 'Which statement correctly describes Elements, Compounds and Mixtures?', '[{"id":"a","label":"Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."},{"id":"b","label":"Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions."},{"id":"c","label":"Most solid solutes become more soluble on heating, while gases usually become less soluble."},{"id":"d","label":"Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."}]', '{"choice":"d"}', 'Chromatography separates soluble components because they travel at different rates between stationary and mobile phases.', 4, 0, 'reviewed', 1),
('viii-chem-elements-compounds-mixtures-q5', 'topic-viii-chem-elements-compounds-mixtures', 'single_choice', 'Design a sequence to separate iron filings, ammonium chloride and sand from one dry mixture. Which conclusion is correct?', '[{"id":"a","label":"Precipitation, followed by filtration, washing and drying."},{"id":"b","label":"Pb²⁺ (lead(II))."},{"id":"c","label":"Magnetic separation, then sublimation, leaving sand."},{"id":"d","label":"32 g O₂."}]', '{"choice":"c"}', 'Use a magnet to remove the magnetic iron filings. Heat the remaining mixture gently under an inverted funnel so ammonium chloride sublimes and deposits on the cool surface. The non-subliming sand remains in the dish and is collected after cooling.', 2, 1, 'reviewed', 1);
