INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-viii-chem-atomic-structure', 'CISCE', NULL, 'VIII', 'Chemistry', 'Atoms', 'Atomic Structure', 'Describe subatomic particles, atomic and mass numbers, isotopes and electronic arrangements of the first twenty elements.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-atomic-structure', 'topic-viii-chem-atomic-structure', 'Atomic Structure', 'Atoms contain a tiny, dense nucleus made of positively charged protons and neutral neutrons, surrounded by negatively charged electrons arranged in shells. Atomic number is the number of protons and identifies the element; a neutral atom has the same number of electrons. Mass number is the total number of protons and neutrons, so neutrons equal mass number minus atomic number. Electrons fill shells in simple arrangements for the first twenty elements, commonly represented as 2, 8, 8, 2. Valence electrons occupy the outermost shell and strongly influence chemical behaviour. Isotopes are atoms of the same element with equal atomic number but different neutron and mass numbers. They have nearly identical chemical properties but different masses and sometimes different nuclear stability. Ions form when atoms lose or gain electrons; the nucleus does not change during ordinary ion formation.', '["Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons.","Electrons occupy shells, and the outermost-shell electrons are called valence electrons.","Isotopes have the same atomic number but different mass numbers because their neutron counts differ.","Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."]', '{"prompt":"An atom has atomic number 17 and mass number 37. Find its protons, electrons, neutrons and shell arrangement.","steps":["Atomic number 17 means 17 protons and, because the atom is neutral, 17 electrons.","Neutrons = mass number − atomic number = 37 − 17 = 20.","Distribute 17 electrons into shells: 2 in the first, 8 in the second and 7 in the third."],"answer":"17 protons, 17 electrons, 20 neutrons; 2,8,7."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-atomic-structure-q1', 'topic-viii-chem-atomic-structure', 'single_choice', 'Which statement correctly describes Atomic Structure?', '[{"id":"a","label":"Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons."},{"id":"b","label":"The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint."},{"id":"c","label":"Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water."},{"id":"d","label":"Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."}]', '{"choice":"a"}', 'Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons.', 1, 0, 'reviewed', 1),
('viii-chem-atomic-structure-q2', 'topic-viii-chem-atomic-structure', 'single_choice', 'Which statement correctly describes Atomic Structure?', '[{"id":"a","label":"Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions."},{"id":"b","label":"Electrons occupy shells, and the outermost-shell electrons are called valence electrons."},{"id":"c","label":"Most solid solutes become more soluble on heating, while gases usually become less soluble."},{"id":"d","label":"Temporary hardness can be removed by boiling; permanent hardness requires methods such as washing soda, ion exchange or distillation."}]', '{"choice":"b"}', 'Electrons occupy shells, and the outermost-shell electrons are called valence electrons.', 2, 0, 'reviewed', 1),
('viii-chem-atomic-structure-q3', 'topic-viii-chem-atomic-structure', 'single_choice', 'Which statement correctly describes Atomic Structure?', '[{"id":"a","label":"Purification methods remove different hazards: filtration removes suspended solids, while boiling or disinfection controls microorganisms."},{"id":"b","label":"Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings."},{"id":"c","label":"Isotopes have the same atomic number but different mass numbers because their neutron counts differ."},{"id":"d","label":"Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another."}]', '{"choice":"c"}', 'Isotopes have the same atomic number but different mass numbers because their neutron counts differ.', 3, 0, 'reviewed', 1),
('viii-chem-atomic-structure-q4', 'topic-viii-chem-atomic-structure', 'single_choice', 'Which statement correctly describes Atomic Structure?', '[{"id":"a","label":"Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide."},{"id":"b","label":"Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."},{"id":"c","label":"Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements."},{"id":"d","label":"Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."}]', '{"choice":"d"}', 'Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus.', 4, 0, 'reviewed', 1),
('viii-chem-atomic-structure-q5', 'topic-viii-chem-atomic-structure', 'single_choice', 'An atom has atomic number 17 and mass number 37. Find its protons, electrons, neutrons and shell arrangement. Which conclusion is correct?', '[{"id":"a","label":"It is very soluble; acidity requires water for ionisation."},{"id":"b","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"c","label":"To limit decomposition and obtain purer nitric acid."},{"id":"d","label":"17 protons, 17 electrons, 20 neutrons; 2,8,7."}]', '{"choice":"d"}', 'Atomic number 17 means 17 protons and, because the atom is neutral, 17 electrons. Neutrons = mass number − atomic number = 37 − 17 = 20. Distribute 17 electrons into shells: 2 in the first, 8 in the second and 7 in the third.', 2, 1, 'reviewed', 1);
