VALUES
('topic-viii-chem-language-of-chemistry', 'CISCE', NULL, 'VIII', 'Chemistry', 'Symbols and Formulae', 'Language of Chemistry', 'Use symbols, valencies, formulae and balanced equations to represent substances and reactions.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-language-of-chemistry', 'topic-viii-chem-language-of-chemistry', 'Language of Chemistry', 'Chemistry uses symbols for elements and formulae for molecules and ionic compounds. A symbol begins with a capital letter and may have a lower-case second letter. Valency describes combining capacity: sodium has valency one, oxygen two and aluminium three. Formulae are constructed so total positive and negative valencies balance, simplifying subscripts to the lowest whole-number ratio. Polyatomic ions such as ammonium, hydroxide, nitrate, carbonate and sulphate behave as units and require brackets when more than one is present. A chemical equation identifies reactants and products; coefficients are adjusted to conserve each kind of atom. Subscripts must never be changed while balancing because that would change the substance itself. State symbols and conditions add meaning: (s), (l), (g), (aq), heat, pressure or catalyst. A balanced equation expresses conservation of atoms and supports quantitative reasoning.', '["Element symbols have a capital first letter; formula subscripts show the simplest whole-number ratio of atoms or ions.","Valencies or ionic charges must balance to make an electrically neutral compound.","Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion.","Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."]', '{"prompt":"Write the formula of aluminium sulphate and balance its formation from aluminium and sulphuric acid.","steps":["Aluminium is Al³⁺ and sulphate is SO₄²⁻; balancing charges gives Al₂(SO₄)₃.","Start with Al + H₂SO₄ → Al₂(SO₄)₃ + H₂.","Balance aluminium, sulphate and hydrogen to obtain 2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂."],"answer":"Al₂(SO₄)₃; 2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-language-of-chemistry-q1', 'topic-viii-chem-language-of-chemistry', 'single_choice', 'Which statement correctly describes Language of Chemistry?', '[{"id":"a","label":"Element symbols have a capital first letter; formula subscripts show the simplest whole-number ratio of atoms or ions."},{"id":"b","label":"Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings."},{"id":"c","label":"Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another."},{"id":"d","label":"Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide."}]', '{"choice":"a"}', 'Element symbols have a capital first letter; formula subscripts show the simplest whole-number ratio of atoms or ions.', 1, 0, 'reviewed', 1),
('viii-chem-language-of-chemistry-q2', 'topic-viii-chem-language-of-chemistry', 'single_choice', 'Which statement correctly describes Language of Chemistry?', '[{"id":"a","label":"Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."},{"id":"b","label":"Valencies or ionic charges must balance to make an electrically neutral compound."},{"id":"c","label":"Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements."},{"id":"d","label":"Across a period atomic size and metallic character generally decrease, while ionisation potential and electronegativity generally increase."}]', '{"choice":"b"}', 'Valencies or ionic charges must balance to make an electrically neutral compound.', 2, 0, 'reviewed', 1),
('viii-chem-language-of-chemistry-q3', 'topic-viii-chem-language-of-chemistry', 'single_choice', 'Which statement correctly describes Language of Chemistry?', '[{"id":"a","label":"Down a group atomic size and metallic character generally increase because new shells and shielding reduce nuclear attraction on valence electrons."},{"id":"b","label":"Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."},{"id":"c","label":"Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion."},{"id":"d","label":"Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice."}]', '{"choice":"c"}', 'Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion.', 3, 0, 'reviewed', 1),
('viii-chem-language-of-chemistry-q4', 'topic-viii-chem-language-of-chemistry', 'single_choice', 'Which statement correctly describes Language of Chemistry?', '[{"id":"a","label":"Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed."},{"id":"b","label":"Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules."},{"id":"c","label":"In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."},{"id":"d","label":"Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."}]', '{"choice":"d"}', 'Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae.', 4, 0, 'reviewed', 1),
('viii-chem-language-of-chemistry-q5', 'topic-viii-chem-language-of-chemistry', 'single_choice', 'Write the formula of aluminium sulphate and balance its formation from aluminium and sulphuric acid. Which conclusion is correct?', '[{"id":"a","label":"Al₂(SO₄)₃; 2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂."},{"id":"b","label":"35.0 g"},{"id":"c","label":"Melting is physical; burning is chemical."},{"id":"d","label":"Magnetic separation, then sublimation, leaving sand."}]', '{"choice":"a"}', 'Aluminium is Al³⁺ and sulphate is SO₄²⁻; balancing charges gives Al₂(SO₄)₃. Start with Al + H₂SO₄ → Al₂(SO₄)₃ + H₂. Balance aluminium, sulphate and hydrogen to obtain 2Al + 3H₂SO₄ → Al₂(SO₄)₃ + 3H₂.', 2, 1, 'reviewed', 1);
