VALUES
('topic-viii-chem-chemical-reactions', 'CISCE', NULL, 'VIII', 'Chemistry', 'Reactions', 'Chemical Reactions', 'Recognise reaction types, energy changes, catalysts and balanced chemical equations.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-chemical-reactions', 'topic-viii-chem-chemical-reactions', 'Chemical Reactions', 'A chemical reaction converts reactants into products by breaking and forming bonds while conserving atoms. In combination reactions, substances join to form one main product; decomposition reactions split a compound using heat, light or electricity. Displacement occurs when a more reactive element replaces a less reactive one, while double displacement exchanges ions and may produce a precipitate, gas or water. Exothermic reactions transfer energy to the surroundings, often warming them, whereas endothermic reactions absorb energy. Oxidation can be described as gain of oxygen or loss of hydrogen, and reduction as loss of oxygen or gain of hydrogen; these paired processes occur together. A catalyst changes reaction rate without being consumed overall. Conditions such as temperature, concentration, surface area and catalysts affect rate because they change the frequency or effectiveness of particle collisions. Equations should include observations and necessary conditions.', '["Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change.","A more reactive element can displace a less reactive element from its compound.","Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them.","A catalyst changes reaction rate while being regenerated, and reaction rate also depends on temperature, concentration and surface area."]', '{"prompt":"Classify and balance the reaction in which zinc is added to copper sulphate solution.","steps":["Zinc is more reactive than copper, so it replaces copper from copper sulphate.","The word equation is zinc + copper sulphate → zinc sulphate + copper.","The formula equation Zn + CuSO₄ → ZnSO₄ + Cu is already balanced in a 1:1:1:1 ratio."],"answer":"A displacement reaction: Zn + CuSO₄ → ZnSO₄ + Cu."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-chemical-reactions-q1', 'topic-viii-chem-chemical-reactions', 'single_choice', 'Which statement correctly describes Chemical Reactions?', '[{"id":"a","label":"Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change."},{"id":"b","label":"Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."},{"id":"c","label":"Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice."},{"id":"d","label":"Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed."}]', '{"choice":"a"}', 'Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change.', 1, 0, 'reviewed', 1),
('viii-chem-chemical-reactions-q2', 'topic-viii-chem-chemical-reactions', 'single_choice', 'Which statement correctly describes Chemical Reactions?', '[{"id":"a","label":"Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules."},{"id":"b","label":"A more reactive element can displace a less reactive element from its compound."},{"id":"c","label":"In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."},{"id":"d","label":"Acids produce H₃O⁺ in water and alkalis produce OH⁻; indicators and pH reveal the resulting solution conditions."}]', '{"choice":"b"}', 'A more reactive element can displace a less reactive element from its compound.', 2, 0, 'reviewed', 1),
('viii-chem-chemical-reactions-q3', 'topic-viii-chem-chemical-reactions', 'single_choice', 'Which statement correctly describes Chemical Reactions?', '[{"id":"a","label":"A salt results from partial or complete replacement of ionisable hydrogen in an acid by a metal or ammonium ion."},{"id":"b","label":"Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions."},{"id":"c","label":"Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them."},{"id":"d","label":"Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."}]', '{"choice":"c"}', 'Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them.', 3, 0, 'reviewed', 1),
('viii-chem-chemical-reactions-q4', 'topic-viii-chem-chemical-reactions', 'single_choice', 'Which statement correctly describes Chemical Reactions?', '[{"id":"a","label":"Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃."},{"id":"b","label":"Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide."},{"id":"c","label":"Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH."},{"id":"d","label":"A catalyst changes reaction rate while being regenerated, and reaction rate also depends on temperature, concentration and surface area."}]', '{"choice":"d"}', 'A catalyst changes reaction rate while being regenerated, and reaction rate also depends on temperature, concentration and surface area.', 4, 0, 'reviewed', 1),
('viii-chem-chemical-reactions-q5', 'topic-viii-chem-chemical-reactions', 'single_choice', 'Classify and balance the reaction in which zinc is added to copper sulphate solution. Which conclusion is correct?', '[{"id":"a","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"b","label":"A displacement reaction: Zn + CuSO₄ → ZnSO₄ + Cu."},{"id":"c","label":"162.5 g"},{"id":"d","label":"Risk of carbon monoxide; stop, ventilate and improve the air supply."}]', '{"choice":"b"}', 'Zinc is more reactive than copper, so it replaces copper from copper sulphate. The word equation is zinc + copper sulphate → zinc sulphate + copper. The formula equation Zn + CuSO₄ → ZnSO₄ + Cu is already balanced in a 1:1:1:1 ratio.', 2, 1, 'reviewed', 1);
