VALUES
('topic-viii-chem-hydrogen', 'CISCE', NULL, 'VIII', 'Chemistry', 'Study of Elements', 'Hydrogen', 'Explain laboratory preparation, properties, tests and important uses of hydrogen.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-hydrogen', 'topic-viii-chem-hydrogen', 'Hydrogen', 'Hydrogen is the lightest element and commonly exists as diatomic H₂. In the laboratory it can be prepared by reacting a moderately reactive metal such as zinc with dilute hydrochloric or sulphuric acid. The first gas is allowed to escape because it contains air and an explosive hydrogen–air mixture. Hydrogen is colourless, odourless, almost insoluble in water and much less dense than air, so it may be collected over water. A lighted splint gives the characteristic pop test. Hydrogen burns in oxygen with a pale blue flame to form water and releases considerable energy. It also acts as a reducing agent by removing oxygen from heated oxides of less reactive metals, such as copper(II) oxide. Important uses include manufacture of ammonia, hydrogenation of vegetable oils, oxy-hydrogen flames and emerging fuel cells. Safe handling requires keeping hydrogen away from sparks and avoiding untested mixtures with air.', '["Laboratory hydrogen is commonly prepared from zinc and a dilute non-oxidising acid and collected over water.","The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint.","Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water.","Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."]', '{"prompt":"Write the equation for preparing hydrogen from zinc and dilute hydrochloric acid, and state one safety precaution.","steps":["Zinc displaces hydrogen from dilute hydrochloric acid.","Balance atoms to obtain Zn + 2HCl → ZnCl₂ + H₂.","Let the first gas escape before ignition because it may contain an explosive mixture of hydrogen and air."],"answer":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-hydrogen-q1', 'topic-viii-chem-hydrogen', 'single_choice', 'Which statement correctly describes Hydrogen?', '[{"id":"a","label":"Laboratory hydrogen is commonly prepared from zinc and a dilute non-oxidising acid and collected over water."},{"id":"b","label":"Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions."},{"id":"c","label":"Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."},{"id":"d","label":"Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃."}]', '{"choice":"a"}', 'Laboratory hydrogen is commonly prepared from zinc and a dilute non-oxidising acid and collected over water.', 1, 0, 'reviewed', 1),
('viii-chem-hydrogen-q2', 'topic-viii-chem-hydrogen', 'single_choice', 'Which statement correctly describes Hydrogen?', '[{"id":"a","label":"Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide."},{"id":"b","label":"The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint."},{"id":"c","label":"Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH."},{"id":"d","label":"Pb²⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH₄OH."}]', '{"choice":"b"}', 'The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint.', 2, 0, 'reviewed', 1),
('viii-chem-hydrogen-q3', 'topic-viii-chem-hydrogen', 'single_choice', 'Which statement correctly describes Hydrogen?', '[{"id":"a","label":"One mole contains 6.022 × 10²³ entities and has mass equal to the relative atomic or molecular mass expressed in grams."},{"id":"b","label":"At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus."},{"id":"c","label":"Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water."},{"id":"d","label":"A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers."}]', '{"choice":"c"}', 'Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water.', 3, 0, 'reviewed', 1),
('viii-chem-hydrogen-q4', 'topic-viii-chem-hydrogen', 'single_choice', 'Which statement correctly describes Hydrogen?', '[{"id":"a","label":"Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."},{"id":"b","label":"Cations move to the cathode and gain electrons; anions move to the anode and lose electrons."},{"id":"c","label":"Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active."},{"id":"d","label":"Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."}]', '{"choice":"d"}', 'Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells.', 4, 0, 'reviewed', 1),
('viii-chem-hydrogen-q5', 'topic-viii-chem-hydrogen', 'single_choice', 'Write the equation for preparing hydrogen from zinc and dilute hydrochloric acid, and state one safety precaution. Which conclusion is correct?', '[{"id":"a","label":"Precipitation, followed by filtration, washing and drying."},{"id":"b","label":"Pb²⁺ (lead(II))."},{"id":"c","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"d","label":"32 g O₂."}]', '{"choice":"c"}', 'Zinc displaces hydrogen from dilute hydrochloric acid. Balance atoms to obtain Zn + 2HCl → ZnCl₂ + H₂. Let the first gas escape before ignition because it may contain an explosive mixture of hydrogen and air.', 2, 1, 'reviewed', 1);
