VALUES
('topic-viii-chem-water', 'CISCE', NULL, 'VIII', 'Chemistry', 'Water', 'Water', 'Explain solutions, solubility, water of crystallisation, hardness and common purification methods.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-water', 'topic-viii-chem-water', 'Water', 'Water is a polar solvent that dissolves many ionic and molecular substances, but not every substance. A solution contains a solute uniformly dispersed in a solvent. Solubility is the maximum mass of solute that dissolves in a stated mass of solvent at a specified temperature to form a saturated solution. For most solids solubility increases with temperature, while gases generally become less soluble as temperature rises. Crystals may include water of crystallisation in a fixed ratio, as in hydrated copper(II) sulphate. Hard water contains dissolved calcium or magnesium ions and forms scum instead of a quick lather with soap. Temporary hardness due mainly to hydrogencarbonates can be removed by boiling; permanent hardness caused by chlorides or sulphates needs washing soda, ion exchange or distillation. Sedimentation, filtration, chlorination and boiling address different impurities, so safe treatment uses the method suited to the contamination.', '["Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions.","Most solid solutes become more soluble on heating, while gases usually become less soluble.","Temporary hardness can be removed by boiling; permanent hardness requires methods such as washing soda, ion exchange or distillation.","Purification methods remove different hazards: filtration removes suspended solids, while boiling or disinfection controls microorganisms."]', '{"prompt":"At 40 °C, 65 g of a salt dissolves in 100 g of water. How much dissolves in 250 g of water at the same temperature?","steps":["Set a proportion because temperature and solvent are unchanged: 65 g salt per 100 g water.","For 250 g water, mass = 65 × 250 ÷ 100.","Calculate 162.5 g of salt."],"answer":"162.5 g"}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-water-q1', 'topic-viii-chem-water', 'single_choice', 'Which statement correctly describes Water?', '[{"id":"a","label":"Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions."},{"id":"b","label":"At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus."},{"id":"c","label":"A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers."},{"id":"d","label":"Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."}]', '{"choice":"a"}', 'Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions.', 1, 0, 'reviewed', 1),
('viii-chem-water-q2', 'topic-viii-chem-water', 'single_choice', 'Which statement correctly describes Water?', '[{"id":"a","label":"Cations move to the cathode and gain electrons; anions move to the anode and lose electrons."},{"id":"b","label":"Most solid solutes become more soluble on heating, while gases usually become less soluble."},{"id":"c","label":"Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active."},{"id":"d","label":"Molten lead bromide produces Pb at the cathode and Br₂ at the anode."}]', '{"choice":"b"}', 'Most solid solutes become more soluble on heating, while gases usually become less soluble.', 2, 0, 'reviewed', 1),
('viii-chem-water-q3', 'topic-viii-chem-water', 'single_choice', 'Which statement correctly describes Water?', '[{"id":"a","label":"In electroplating the article is cathode, the coating metal is generally anode and a soluble salt supplies metal ions."},{"id":"b","label":"An ore is a mineral from which a metal can be extracted conveniently and economically."},{"id":"c","label":"Temporary hardness can be removed by boiling; permanent hardness requires methods such as washing soda, ion exchange or distillation."},{"id":"d","label":"Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air."}]', '{"choice":"c"}', 'Temporary hardness can be removed by boiling; permanent hardness requires methods such as washing soda, ion exchange or distillation.', 3, 0, 'reviewed', 1),
('viii-chem-water-q4', 'topic-viii-chem-water', 'single_choice', 'Which statement correctly describes Water?', '[{"id":"a","label":"Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically."},{"id":"b","label":"Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."},{"id":"c","label":"HCl gas is highly soluble in water, denser than air and collected by downward displacement of air."},{"id":"d","label":"Purification methods remove different hazards: filtration removes suspended solids, while boiling or disinfection controls microorganisms."}]', '{"choice":"d"}', 'Purification methods remove different hazards: filtration removes suspended solids, while boiling or disinfection controls microorganisms.', 4, 0, 'reviewed', 1),
('viii-chem-water-q5', 'topic-viii-chem-water', 'single_choice', 'At 40 °C, 65 g of a salt dissolves in 100 g of water. How much dissolves in 250 g of water at the same temperature? Which conclusion is correct?', '[{"id":"a","label":"It is very soluble; acidity requires water for ionisation."},{"id":"b","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"c","label":"To limit decomposition and obtain purer nitric acid."},{"id":"d","label":"162.5 g"}]', '{"choice":"d"}', 'Set a proportion because temperature and solvent are unchanged: 65 g salt per 100 g water. For 250 g water, mass = 65 × 250 ÷ 100. Calculate 162.5 g of salt.', 2, 1, 'reviewed', 1);
