VALUES
('topic-viii-chem-carbon-compounds', 'CISCE', NULL, 'VIII', 'Chemistry', 'Carbon', 'Carbon and its Compounds', 'Relate carbon allotropes and simple carbon compounds to their structures, properties and environmental effects.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-viii-chem-carbon-compounds', 'topic-viii-chem-carbon-compounds', 'Carbon and its Compounds', 'Carbon is unusual because each atom forms four covalent bonds and can link to other carbon atoms, producing a vast range of compounds. It occurs in crystalline allotropes such as diamond and graphite and in amorphous forms such as coal, coke and charcoal. Diamond has a rigid three-dimensional network, making it extremely hard and an electrical insulator. Graphite has layered sheets with mobile electrons, so it is soft, slippery and electrically conducting. Carbon burns in sufficient oxygen to form carbon dioxide; limited oxygen can produce poisonous carbon monoxide. Carbon dioxide is colourless, denser than air, turns limewater milky and does not support ordinary combustion. It is needed for photosynthesis but excessive atmospheric carbon dioxide strengthens the greenhouse effect. Carbon monoxide binds strongly to haemoglobin and prevents oxygen transport. Fuels must therefore burn with adequate ventilation, and charcoal is useful in adsorption because of its porous surface.', '["Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings.","Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another.","Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide.","Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."]', '{"prompt":"A burner shows a yellow, smoky flame in a closed kitchen. Explain the danger and the immediate correction.","steps":["The yellow smoky flame indicates incomplete combustion because too little oxygen reaches the fuel.","Incomplete combustion can produce carbon monoxide, which blocks oxygen transport in blood.","Turn off the burner, ventilate the room and restore a clear air inlet before reuse."],"answer":"Risk of carbon monoxide; stop, ventilate and improve the air supply."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('viii-chem-carbon-compounds-q1', 'topic-viii-chem-carbon-compounds', 'single_choice', 'Which statement correctly describes Carbon and its Compounds?', '[{"id":"a","label":"Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings."},{"id":"b","label":"An ore is a mineral from which a metal can be extracted conveniently and economically."},{"id":"c","label":"Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air."},{"id":"d","label":"Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically."}]', '{"choice":"a"}', 'Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings.', 1, 0, 'reviewed', 1),
('viii-chem-carbon-compounds-q2', 'topic-viii-chem-carbon-compounds', 'single_choice', 'Which statement correctly describes Carbon and its Compounds?', '[{"id":"a","label":"Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."},{"id":"b","label":"Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another."},{"id":"c","label":"HCl gas is highly soluble in water, denser than air and collected by downward displacement of air."},{"id":"d","label":"Dry HCl is not acidic to dry litmus; water enables ionisation to H₃O⁺ and Cl⁻."}]', '{"choice":"b"}', 'Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another.', 2, 0, 'reviewed', 1),
('viii-chem-carbon-compounds-q3', 'topic-viii-chem-carbon-compounds', 'single_choice', 'Which statement correctly describes Carbon and its Compounds?', '[{"id":"a","label":"HCl and NH₃ form dense white fumes of NH₄Cl."},{"id":"b","label":"Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide."},{"id":"c","label":"Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide."},{"id":"d","label":"Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime."}]', '{"choice":"c"}', 'Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide.', 3, 0, 'reviewed', 1),
('viii-chem-carbon-compounds-q4', 'topic-viii-chem-carbon-compounds', 'single_choice', 'Which statement correctly describes Carbon and its Compounds?', '[{"id":"a","label":"Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution."},{"id":"b","label":"The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature."},{"id":"c","label":"Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper."},{"id":"d","label":"Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."}]', '{"choice":"d"}', 'Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface.', 4, 0, 'reviewed', 1),
('viii-chem-carbon-compounds-q5', 'topic-viii-chem-carbon-compounds', 'single_choice', 'A burner shows a yellow, smoky flame in a closed kitchen. Explain the danger and the immediate correction. Which conclusion is correct?', '[{"id":"a","label":"Risk of carbon monoxide; stop, ventilate and improve the air supply."},{"id":"b","label":"35.0 g"},{"id":"c","label":"Melting is physical; burning is chemical."},{"id":"d","label":"Magnetic separation, then sublimation, leaving sand."}]', '{"choice":"a"}', 'The yellow smoky flame indicates incomplete combustion because too little oxygen reaches the fuel. Incomplete combustion can produce carbon monoxide, which blocks oxygen transport in blood. Turn off the burner, ventilate the room and restore a clear air inlet before reuse.', 2, 1, 'reviewed', 1);
