VALUES
('topic-x-chem-periodic-properties', 'CISCE', 2027, 'X', 'Chemistry', 'Periodic Properties', 'Periodic Table, Periodic Properties and Variations of Properties', 'Explain periodic trends through nuclear charge, shells and valence electrons for elements through calcium.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-periodic-properties', 'topic-x-chem-periodic-properties', 'Periodic Table, Periodic Properties and Variations of Properties', 'The modern periodic law states that the physical and chemical properties of elements are periodic functions of atomic number. Elements are arranged in periods according to occupied electron shells and in groups according to related valence-shell configurations. Across a period, nuclear charge rises while electrons enter the same principal shell, so atomic size generally decreases, ionisation potential and electronegativity generally increase, and metallic character decreases. Down a group, additional shells increase size and shielding, so ionisation potential and electronegativity generally decrease while metallic character increases. Electron affinity and non-metallic character show corresponding trends with qualifications. Alkali metals readily lose one electron and become more reactive down the group; halogens tend to gain one electron, with reactivity generally decreasing down their group. Trends are explanations, not isolated arrows: effective nuclear attraction and shell structure must support every prediction.', '["Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements.","Across a period atomic size and metallic character generally decrease, while ionisation potential and electronegativity generally increase.","Down a group atomic size and metallic character generally increase because new shells and shielding reduce nuclear attraction on valence electrons.","Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."]', '{"prompt":"Compare sodium and chlorine in Period 3 for atomic size, metallic character and electronegativity.","steps":["Both have three occupied shells, but chlorine has a much larger nuclear charge.","The stronger attraction in chlorine pulls its electron cloud closer, so chlorine is smaller.","Sodium is more metallic and less electronegative; chlorine is less metallic and more electronegative."],"answer":"Na is larger and more metallic; Cl is smaller and more electronegative."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-periodic-properties-q1', 'topic-x-chem-periodic-properties', 'single_choice', 'Which statement correctly describes Periodic Table, Periodic Properties and Variations of Properties?', '[{"id":"a","label":"Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements."},{"id":"b","label":"Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide."},{"id":"c","label":"Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime."},{"id":"d","label":"Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution."}]', '{"choice":"a"}', 'Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements.', 1, 0, 'reviewed', 1),
('x-chem-periodic-properties-q2', 'topic-x-chem-periodic-properties', 'single_choice', 'Which statement correctly describes Periodic Table, Periodic Properties and Variations of Properties?', '[{"id":"a","label":"The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature."},{"id":"b","label":"Across a period atomic size and metallic character generally decrease, while ionisation potential and electronegativity generally increase."},{"id":"c","label":"Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper."},{"id":"d","label":"Laboratory HNO₃ is displaced from a nitrate by concentrated H₂SO₄ and collected by condensation."}]', '{"choice":"b"}', 'Across a period atomic size and metallic character generally decrease, while ionisation potential and electronegativity generally increase.', 2, 0, 'reviewed', 1),
('x-chem-periodic-properties-q3', 'topic-x-chem-periodic-properties', 'single_choice', 'Which statement correctly describes Periodic Table, Periodic Properties and Variations of Properties?', '[{"id":"a","label":"The Ostwald process oxidises NH₃ to NO, then NO₂, followed by absorption to form nitric acid."},{"id":"b","label":"Nitric acid usually does not release H₂ from metals because it is a strong oxidising agent."},{"id":"c","label":"Down a group atomic size and metallic character generally increase because new shells and shielding reduce nuclear attraction on valence electrons."},{"id":"d","label":"Concentrated nitric acid passivates iron and aluminium by forming a protective oxide layer."}]', '{"choice":"c"}', 'Down a group atomic size and metallic character generally increase because new shells and shielding reduce nuclear attraction on valence electrons.', 3, 0, 'reviewed', 1),
('x-chem-periodic-properties-q4', 'topic-x-chem-periodic-properties', 'single_choice', 'Which statement correctly describes Periodic Table, Periodic Properties and Variations of Properties?', '[{"id":"a","label":"The Contact process uses V₂O₅ to catalyse 2SO₂ + O₂ ⇌ 2SO₃ under compromise conditions."},{"id":"b","label":"SO₃ is absorbed in concentrated H₂SO₄ to form oleum before dilution, avoiding acid mist."},{"id":"c","label":"Dilute H₂SO₄ shows ordinary acidic reactions; concentrated acid can oxidise and dehydrate."},{"id":"d","label":"Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."}]', '{"choice":"d"}', 'Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17.', 4, 0, 'reviewed', 1),
('x-chem-periodic-properties-q5', 'topic-x-chem-periodic-properties', 'single_choice', 'Compare sodium and chlorine in Period 3 for atomic size, metallic character and electronegativity. Which conclusion is correct?', '[{"id":"a","label":"A displacement reaction: Zn + CuSO₄ → ZnSO₄ + Cu."},{"id":"b","label":"Na is larger and more metallic; Cl is smaller and more electronegative."},{"id":"c","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"d","label":"162.5 g"}]', '{"choice":"b"}', 'Both have three occupied shells, but chlorine has a much larger nuclear charge. The stronger attraction in chlorine pulls its electron cloud closer, so chlorine is smaller. Sodium is more metallic and less electronegative; chlorine is less metallic and more electronegative.', 2, 1, 'reviewed', 1);
