VALUES
('topic-x-chem-chemical-bonding', 'CISCE', 2027, 'X', 'Chemistry', 'Bonding', 'Chemical Bonding', 'Represent electrovalent, covalent and coordinate bonds and connect bonding with properties.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-chemical-bonding', 'topic-x-chem-chemical-bonding', 'Chemical Bonding', 'Atoms bond to achieve more stable outer-electron arrangements. Electrovalent or ionic bonding involves electron transfer followed by attraction between oppositely charged ions, as in sodium chloride, magnesium chloride and calcium oxide. Ionic compounds form crystal lattices, have high melting points and conduct electricity only when molten or dissolved because ions must be mobile. Covalent bonds form when atoms share electron pairs. Non-polar molecules share approximately equally, while polar covalent bonds arise from unequal attraction caused by electronegativity differences, as in hydrogen chloride, ammonia and water. Covalent substances often have lower melting and boiling points and usually do not conduct electricity, although structure matters. A coordinate bond is a shared pair supplied entirely by one atom, illustrated when ammonia donates its lone pair to H⁺ to form NH₄⁺ or water forms H₃O⁺. Electron-dot diagrams must show valence electrons and the origin of shared or transferred pairs accurately.', '["Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice.","Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed.","Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules.","In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."]', '{"prompt":"Explain why solid sodium chloride does not conduct but molten sodium chloride does.","steps":["Current requires charged particles that can move through the material.","In solid NaCl, Na⁺ and Cl⁻ ions are locked in fixed lattice positions.","Melting frees the ions to migrate to electrodes, so the molten compound conducts."],"answer":"Ions are fixed in the solid but mobile in the melt."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-chemical-bonding-q1', 'topic-x-chem-chemical-bonding', 'single_choice', 'Which statement correctly describes Chemical Bonding?', '[{"id":"a","label":"Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice."},{"id":"b","label":"Nitric acid usually does not release H₂ from metals because it is a strong oxidising agent."},{"id":"c","label":"Concentrated nitric acid passivates iron and aluminium by forming a protective oxide layer."},{"id":"d","label":"The Contact process uses V₂O₅ to catalyse 2SO₂ + O₂ ⇌ 2SO₃ under compromise conditions."}]', '{"choice":"a"}', 'Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice.', 1, 0, 'reviewed', 1),
('x-chem-chemical-bonding-q2', 'topic-x-chem-chemical-bonding', 'single_choice', 'Which statement correctly describes Chemical Bonding?', '[{"id":"a","label":"SO₃ is absorbed in concentrated H₂SO₄ to form oleum before dilution, avoiding acid mist."},{"id":"b","label":"Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed."},{"id":"c","label":"Dilute H₂SO₄ shows ordinary acidic reactions; concentrated acid can oxidise and dehydrate."},{"id":"d","label":"Sulphate ions give a white insoluble BaSO₄ precipitate with a soluble barium salt after acidification."}]', '{"choice":"b"}', 'Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed.', 2, 0, 'reviewed', 1),
('x-chem-chemical-bonding-q3', 'topic-x-chem-chemical-bonding', 'single_choice', 'Which statement correctly describes Chemical Bonding?', '[{"id":"a","label":"A homologous series shares a functional group and general formula; adjacent members differ by CH₂."},{"id":"b","label":"Alkanes are saturated, while alkenes and alkynes are unsaturated and undergo addition reactions."},{"id":"c","label":"Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules."},{"id":"d","label":"Compounds can share a molecular formula but have different structural arrangements called isomers."}]', '{"choice":"c"}', 'Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules.', 3, 0, 'reviewed', 1),
('x-chem-chemical-bonding-q4', 'topic-x-chem-chemical-bonding', 'single_choice', 'Which statement correctly describes Chemical Bonding?', '[{"id":"a","label":"Ethanol oxidises to ethanoic acid, and ethanol plus ethanoic acid forms an ester and water."},{"id":"b","label":"Particles of matter are in continuous motion, and their average kinetic energy rises when temperature rises."},{"id":"c","label":"Solids have the least inter-particle space and strongest effective attraction; gases have the greatest space and weakest attraction."},{"id":"d","label":"In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."}]', '{"choice":"d"}', 'In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺.', 4, 0, 'reviewed', 1),
('x-chem-chemical-bonding-q5', 'topic-x-chem-chemical-bonding', 'single_choice', 'Explain why solid sodium chloride does not conduct but molten sodium chloride does. Which conclusion is correct?', '[{"id":"a","label":"Precipitation, followed by filtration, washing and drying."},{"id":"b","label":"Pb²⁺ (lead(II))."},{"id":"c","label":"Ions are fixed in the solid but mobile in the melt."},{"id":"d","label":"32 g O₂."}]', '{"choice":"c"}', 'Current requires charged particles that can move through the material. In solid NaCl, Na⁺ and Cl⁻ ions are locked in fixed lattice positions. Melting frees the ions to migrate to electrodes, so the molten compound conducts.', 2, 1, 'reviewed', 1);
