INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-acids-bases-salts', 'CISCE', 2027, 'X', 'Chemistry', 'Acids, Bases and Salts', 'Acids, Bases and Salts', 'Apply ionic definitions, indicators, pH, salt classification and preparation methods with balanced equations.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-acids-bases-salts', 'topic-x-chem-acids-bases-salts', 'Acids, Bases and Salts', 'Acids ionise in water to produce hydronium ions, while alkalis dissociate to provide hydroxide ions. Their properties therefore appear in aqueous solution. Indicators respond over characteristic pH ranges: acids turn blue litmus red, alkalis turn red litmus blue, methyl orange is red in acid and yellow in alkali, and phenolphthalein is colourless in acid but pink in alkali. The pH scale expresses acidity or alkalinity, with 7 neutral under ordinary conditions. Salts form when acidic hydrogen is partly or completely replaced by a metal or ammonium ion and may be normal, acid, basic or complex. Preparation depends on solubility and reactant type: direct combination, displacement, precipitation, neutralisation, titration, or acid action on carbonates. Acids decompose carbonates and hydrogencarbonates to release carbon dioxide and react with suitable sulphides or sulphites to release characteristic gases. Correct equations must show ionisation, conditions and observations.', '["Acids produce H₃O⁺ in water and alkalis produce OH⁻; indicators and pH reveal the resulting solution conditions.","A salt results from partial or complete replacement of ionisable hydrogen in an acid by a metal or ammonium ion.","Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions.","Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."]', '{"prompt":"Choose a method to prepare pure dry lead(II) sulphate from soluble reagents.","steps":["Lead(II) sulphate is insoluble, so use precipitation.","Mix lead(II) nitrate solution with sodium sulphate solution: Pb(NO₃)₂ + Na₂SO₄ → PbSO₄↓ + 2NaNO₃.","Filter the precipitate, wash it with distilled water and dry it."],"answer":"Precipitation, followed by filtration, washing and drying."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-acids-bases-salts-q1', 'topic-x-chem-acids-bases-salts', 'single_choice', 'Which statement correctly describes Acids, Bases and Salts?', '[{"id":"a","label":"Acids produce H₃O⁺ in water and alkalis produce OH⁻; indicators and pH reveal the resulting solution conditions."},{"id":"b","label":"Alkanes are saturated, while alkenes and alkynes are unsaturated and undergo addition reactions."},{"id":"c","label":"Compounds can share a molecular formula but have different structural arrangements called isomers."},{"id":"d","label":"Ethanol oxidises to ethanoic acid, and ethanol plus ethanoic acid forms an ester and water."}]', '{"choice":"a"}', 'Acids produce H₃O⁺ in water and alkalis produce OH⁻; indicators and pH reveal the resulting solution conditions.', 1, 0, 'reviewed', 1),
('x-chem-acids-bases-salts-q2', 'topic-x-chem-acids-bases-salts', 'single_choice', 'Which statement correctly describes Acids, Bases and Salts?', '[{"id":"a","label":"Particles of matter are in continuous motion, and their average kinetic energy rises when temperature rises."},{"id":"b","label":"A salt results from partial or complete replacement of ionisable hydrogen in an acid by a metal or ammonium ion."},{"id":"c","label":"Solids have the least inter-particle space and strongest effective attraction; gases have the greatest space and weakest attraction."},{"id":"d","label":"Changes of state alter particle arrangement and energy but do not change the chemical identity of a pure substance."}]', '{"choice":"b"}', 'A salt results from partial or complete replacement of ionisable hydrogen in an acid by a metal or ammonium ion.', 2, 0, 'reviewed', 1),
('x-chem-acids-bases-salts-q3', 'topic-x-chem-acids-bases-salts', 'single_choice', 'Which statement correctly describes Acids, Bases and Salts?', '[{"id":"a","label":"In a closed system, total mass of reactants equals total mass of products, including any gas that participates in the reaction."},{"id":"b","label":"A physical change preserves chemical composition even when state, size, shape or appearance changes."},{"id":"c","label":"Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions."},{"id":"d","label":"A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds."}]', '{"choice":"c"}', 'Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions.', 3, 0, 'reviewed', 1),
('x-chem-acids-bases-salts-q4', 'topic-x-chem-acids-bases-salts', 'single_choice', 'Which statement correctly describes Acids, Bases and Salts?', '[{"id":"a","label":"Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction."},{"id":"b","label":"Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes."},{"id":"c","label":"Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions."},{"id":"d","label":"Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."}]', '{"choice":"d"}', 'Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide.', 4, 0, 'reviewed', 1),
('x-chem-acids-bases-salts-q5', 'topic-x-chem-acids-bases-salts', 'single_choice', 'Choose a method to prepare pure dry lead(II) sulphate from soluble reagents. Which conclusion is correct?', '[{"id":"a","label":"It is very soluble; acidity requires water for ionisation."},{"id":"b","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"c","label":"To limit decomposition and obtain purer nitric acid."},{"id":"d","label":"Precipitation, followed by filtration, washing and drying."}]', '{"choice":"d"}', 'Lead(II) sulphate is insoluble, so use precipitation. Mix lead(II) nitrate solution with sodium sulphate solution: Pb(NO₃)₂ + Na₂SO₄ → PbSO₄↓ + 2NaNO₃. Filter the precipitate, wash it with distilled water and dry it.', 2, 1, 'reviewed', 1);
