INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-analytical-chemistry', 'CISCE', 2027, 'X', 'Chemistry', 'Qualitative Analysis', 'Analytical Chemistry', 'Identify selected cations from precipitate colours and behaviour with sodium and ammonium hydroxides.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-analytical-chemistry', 'topic-x-chem-analytical-chemistry', 'Analytical Chemistry', 'Qualitative analysis identifies ions through reproducible observations. Solutions of iron, copper, zinc and lead salts may be tested with sodium hydroxide and ammonium hydroxide added first dropwise and then in excess. Iron(II) gives a dirty green hydroxide precipitate that slowly turns brown on oxidation, while iron(III) gives a reddish-brown precipitate. Copper(II) gives a light blue precipitate; in excess ammonium hydroxide it dissolves to form a deep inky-blue solution. Zinc gives a white gelatinous precipitate soluble in excess sodium hydroxide and also in excess ammonium hydroxide. Lead gives a white precipitate soluble in excess sodium hydroxide but not in excess ammonium hydroxide. Amphoteric aluminium, zinc and lead oxides or hydroxides react with strong alkalis as well as acids. A conclusion must follow the complete sequence of colour and solubility observations rather than one colour viewed in isolation.', '["Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃.","Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide.","Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH.","Pb²⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH₄OH."]', '{"prompt":"An unknown solution gives a white precipitate with NaOH that dissolves in excess, but its white precipitate with NH₄OH does not dissolve in excess. Identify the cation.","steps":["Solubility in excess NaOH suggests an amphoteric hydroxide such as zinc or lead.","Zinc hydroxide also dissolves in excess NH₄OH, but the observed precipitate does not.","The pattern therefore identifies Pb²⁺."],"answer":"Pb²⁺ (lead(II))."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-analytical-chemistry-q1', 'topic-x-chem-analytical-chemistry', 'single_choice', 'Which statement correctly describes Analytical Chemistry?', '[{"id":"a","label":"Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃."},{"id":"b","label":"A physical change preserves chemical composition even when state, size, shape or appearance changes."},{"id":"c","label":"A chemical change forms new substance or substances through rearrangement of atoms and chemical bonds."},{"id":"d","label":"Gas evolution, precipitate formation, persistent colour change and unexpected energy change are common evidence of reaction."}]', '{"choice":"a"}', 'Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃.', 1, 0, 'reviewed', 1),
('x-chem-analytical-chemistry-q2', 'topic-x-chem-analytical-chemistry', 'single_choice', 'Which statement correctly describes Analytical Chemistry?', '[{"id":"a","label":"Reversibility alone does not define a physical change; the decisive question is whether chemical composition changes."},{"id":"b","label":"Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide."},{"id":"c","label":"Elements contain one kind of atom; compounds contain elements chemically combined in fixed proportions."},{"id":"d","label":"Mixtures have variable composition and usually retain the properties of their components."}]', '{"choice":"b"}', 'Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide.', 2, 0, 'reviewed', 1),
('x-chem-analytical-chemistry-q3', 'topic-x-chem-analytical-chemistry', 'single_choice', 'Which statement correctly describes Analytical Chemistry?', '[{"id":"a","label":"A separation technique is selected from differences in solubility, particle size, density, magnetism, sublimation or boiling point."},{"id":"b","label":"Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."},{"id":"c","label":"Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH."},{"id":"d","label":"Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons."}]', '{"choice":"c"}', 'Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH.', 3, 0, 'reviewed', 1),
('x-chem-analytical-chemistry-q4', 'topic-x-chem-analytical-chemistry', 'single_choice', 'Which statement correctly describes Analytical Chemistry?', '[{"id":"a","label":"Electrons occupy shells, and the outermost-shell electrons are called valence electrons."},{"id":"b","label":"Isotopes have the same atomic number but different mass numbers because their neutron counts differ."},{"id":"c","label":"Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."},{"id":"d","label":"Pb²⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH₄OH."}]', '{"choice":"d"}', 'Pb²⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH₄OH.', 4, 0, 'reviewed', 1),
('x-chem-analytical-chemistry-q5', 'topic-x-chem-analytical-chemistry', 'single_choice', 'An unknown solution gives a white precipitate with NaOH that dissolves in excess, but its white precipitate with NH₄OH does not dissolve in excess. Identify the cation. Which conclusion is correct?', '[{"id":"a","label":"Pb²⁺ (lead(II))."},{"id":"b","label":"35.0 g"},{"id":"c","label":"Melting is physical; burning is chemical."},{"id":"d","label":"Magnetic separation, then sublimation, leaving sand."}]', '{"choice":"a"}', 'Solubility in excess NaOH suggests an amphoteric hydroxide such as zinc or lead. Zinc hydroxide also dissolves in excess NH₄OH, but the observed precipitate does not. The pattern therefore identifies Pb²⁺.', 2, 1, 'reviewed', 1);
