  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-mole-stoichiometry', 'CISCE', 2027, 'X', 'Chemistry', 'Quantitative Chemistry', 'Mole Concept and Stoichiometry', 'Use the mole, Avogadro constant, gas volume laws, formula calculations and balanced equations quantitatively.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-mole-stoichiometry', 'topic-x-chem-mole-stoichiometry', 'Mole Concept and Stoichiometry', 'A mole is the amount containing Avogadro’s number, 6.022 × 10²³, of specified particles. One mole of atoms has a mass numerically equal to relative atomic mass in grams, and one mole of molecules has a mass equal to relative molecular mass in grams. At standard temperature and pressure in the syllabus convention, one mole of gas occupies 22.4 litres. Avogadro’s law states that equal volumes of gases at the same temperature and pressure contain equal numbers of molecules. Gay-Lussac’s law shows that reacting gas volumes and gaseous products occur in simple whole-number ratios under the same conditions. Vapour density is half relative molecular mass. Empirical formula gives the simplest atom ratio, while molecular formula is a whole-number multiple determined from molar mass. Balanced equations provide mole ratios for converting masses, gas volumes and particle counts, with units and limiting information checked before calculation.', '["One mole contains 6.022 × 10²³ entities and has mass equal to the relative atomic or molecular mass expressed in grams.","At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus.","A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers.","Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."]', '{"prompt":"Calculate the mass of oxygen needed to burn 12 g of carbon completely: C + O₂ → CO₂.","steps":["Moles of carbon = 12 g ÷ 12 g mol⁻¹ = 1 mol.","The equation shows 1 mol C reacts with 1 mol O₂.","One mole of O₂ has mass 32 g, so 32 g oxygen is required."],"answer":"32 g O₂."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-mole-stoichiometry-q1', 'topic-x-chem-mole-stoichiometry', 'single_choice', 'Which statement correctly describes Mole Concept and Stoichiometry?', '[{"id":"a","label":"One mole contains 6.022 × 10²³ entities and has mass equal to the relative atomic or molecular mass expressed in grams."},{"id":"b","label":"Chromatography separates soluble components because they travel at different rates between stationary and mobile phases."},{"id":"c","label":"Atomic number equals proton number and, for a neutral atom, electron number; mass number equals protons plus neutrons."},{"id":"d","label":"Electrons occupy shells, and the outermost-shell electrons are called valence electrons."}]', '{"choice":"a"}', 'One mole contains 6.022 × 10²³ entities and has mass equal to the relative atomic or molecular mass expressed in grams.', 1, 0, 'reviewed', 1),
('x-chem-mole-stoichiometry-q2', 'topic-x-chem-mole-stoichiometry', 'single_choice', 'Which statement correctly describes Mole Concept and Stoichiometry?', '[{"id":"a","label":"Isotopes have the same atomic number but different mass numbers because their neutron counts differ."},{"id":"b","label":"At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus."},{"id":"c","label":"Cations form by electron loss and anions by electron gain; ordinary chemical changes do not alter the nucleus."},{"id":"d","label":"Element symbols have a capital first letter; formula subscripts show the simplest whole-number ratio of atoms or ions."}]', '{"choice":"b"}', 'At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus.', 2, 0, 'reviewed', 1),
('x-chem-mole-stoichiometry-q3', 'topic-x-chem-mole-stoichiometry', 'single_choice', 'Which statement correctly describes Mole Concept and Stoichiometry?', '[{"id":"a","label":"Valencies or ionic charges must balance to make an electrically neutral compound."},{"id":"b","label":"Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion."},{"id":"c","label":"A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers."},{"id":"d","label":"Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."}]', '{"choice":"c"}', 'A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers.', 3, 0, 'reviewed', 1),
('x-chem-mole-stoichiometry-q4', 'topic-x-chem-mole-stoichiometry', 'single_choice', 'Which statement correctly describes Mole Concept and Stoichiometry?', '[{"id":"a","label":"Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change."},{"id":"b","label":"A more reactive element can displace a less reactive element from its compound."},{"id":"c","label":"Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them."},{"id":"d","label":"Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."}]', '{"choice":"d"}', 'Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass.', 4, 0, 'reviewed', 1),
('x-chem-mole-stoichiometry-q5', 'topic-x-chem-mole-stoichiometry', 'single_choice', 'Calculate the mass of oxygen needed to burn 12 g of carbon completely: C + O₂ → CO₂. Which conclusion is correct?', '[{"id":"a","label":"A displacement reaction: Zn + CuSO₄ → ZnSO₄ + Cu."},{"id":"b","label":"32 g O₂."},{"id":"c","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"d","label":"162.5 g"}]', '{"choice":"b"}', 'Moles of carbon = 12 g ÷ 12 g mol⁻¹ = 1 mol. The equation shows 1 mol C reacts with 1 mol O₂. One mole of O₂ has mass 32 g, so 32 g oxygen is required.', 2, 1, 'reviewed', 1);
