INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-electrolysis', 'CISCE', 2027, 'X', 'Chemistry', 'Electrochemistry', 'Electrolysis', 'Explain ion migration, selective discharge, electrode reactions and applications of electrolysis.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-electrolysis', 'topic-x-chem-electrolysis', 'Electrolysis', 'Electrolysis is chemical decomposition caused by electric current through an electrolyte. Electrolytes contain mobile ions when molten or in aqueous solution; non-electrolytes do not provide ions. The cathode is connected to the negative terminal and attracts cations, where reduction by electron gain occurs. The anode is positive and attracts anions, where oxidation by electron loss occurs. Products depend on the ions present, their discharge tendencies, concentration and electrode material. Molten lead bromide yields lead at the cathode and bromine at the anode. Acidified water with inert electrodes yields hydrogen and oxygen, while aqueous copper(II) sulphate behaves differently with platinum and copper electrodes. Electroplating deposits a metal coating: the object is cathode, coating metal is usually anode, and electrolyte supplies coating-metal ions. Electrorefining transfers pure copper to the cathode while less reactive impurities form anode mud. Every analysis should state electrolyte, electrodes, ions, half-equations and observations.', '["Cations move to the cathode and gain electrons; anions move to the anode and lose electrons.","Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active.","Molten lead bromide produces Pb at the cathode and Br₂ at the anode.","In electroplating the article is cathode, the coating metal is generally anode and a soluble salt supplies metal ions."]', '{"prompt":"State the electrode reactions during electrolysis of molten lead bromide.","steps":["Molten PbBr₂ contains mobile Pb²⁺ and Br⁻ ions.","At the cathode, Pb²⁺ gains electrons: Pb²⁺ + 2e⁻ → Pb.","At the anode, bromide loses electrons: 2Br⁻ → Br₂ + 2e⁻."],"answer":"Lead forms at the cathode and bromine at the anode."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-electrolysis-q1', 'topic-x-chem-electrolysis', 'single_choice', 'Which statement correctly describes Electrolysis?', '[{"id":"a","label":"Cations move to the cathode and gain electrons; anions move to the anode and lose electrons."},{"id":"b","label":"Polyatomic ions remain intact in many formulae and are enclosed in brackets when a subscript applies to the whole ion."},{"id":"c","label":"Equations are balanced by changing coefficients, never the subscripts inside correct chemical formulae."},{"id":"d","label":"Combination, decomposition, displacement and double-displacement reactions classify common patterns of chemical change."}]', '{"choice":"a"}', 'Cations move to the cathode and gain electrons; anions move to the anode and lose electrons.', 1, 0, 'reviewed', 1),
('x-chem-electrolysis-q2', 'topic-x-chem-electrolysis', 'single_choice', 'Which statement correctly describes Electrolysis?', '[{"id":"a","label":"A more reactive element can displace a less reactive element from its compound."},{"id":"b","label":"Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active."},{"id":"c","label":"Exothermic reactions release energy to the surroundings; endothermic reactions absorb energy from them."},{"id":"d","label":"A catalyst changes reaction rate while being regenerated, and reaction rate also depends on temperature, concentration and surface area."}]', '{"choice":"b"}', 'Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active.', 2, 0, 'reviewed', 1),
('x-chem-electrolysis-q3', 'topic-x-chem-electrolysis', 'single_choice', 'Which statement correctly describes Electrolysis?', '[{"id":"a","label":"Laboratory hydrogen is commonly prepared from zinc and a dilute non-oxidising acid and collected over water."},{"id":"b","label":"The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint."},{"id":"c","label":"Molten lead bromide produces Pb at the cathode and Br₂ at the anode."},{"id":"d","label":"Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water."}]', '{"choice":"c"}', 'Molten lead bromide produces Pb at the cathode and Br₂ at the anode.', 3, 0, 'reviewed', 1),
('x-chem-electrolysis-q4', 'topic-x-chem-electrolysis', 'single_choice', 'Which statement correctly describes Electrolysis?', '[{"id":"a","label":"Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."},{"id":"b","label":"Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions."},{"id":"c","label":"Most solid solutes become more soluble on heating, while gases usually become less soluble."},{"id":"d","label":"In electroplating the article is cathode, the coating metal is generally anode and a soluble salt supplies metal ions."}]', '{"choice":"d"}', 'In electroplating the article is cathode, the coating metal is generally anode and a soluble salt supplies metal ions.', 4, 0, 'reviewed', 1),
('x-chem-electrolysis-q5', 'topic-x-chem-electrolysis', 'single_choice', 'State the electrode reactions during electrolysis of molten lead bromide. Which conclusion is correct?', '[{"id":"a","label":"Ions are fixed in the solid but mobile in the melt."},{"id":"b","label":"Precipitation, followed by filtration, washing and drying."},{"id":"c","label":"Lead forms at the cathode and bromine at the anode."},{"id":"d","label":"Pb²⁺ (lead(II))."}]', '{"choice":"c"}', 'Molten PbBr₂ contains mobile Pb²⁺ and Br⁻ ions. At the cathode, Pb²⁺ gains electrons: Pb²⁺ + 2e⁻ → Pb. At the anode, bromide loses electrons: 2Br⁻ → Br₂ + 2e⁻.', 2, 1, 'reviewed', 1);
