VALUES
('topic-x-chem-metallurgy', 'CISCE', 2027, 'X', 'Chemistry', 'Metals', 'Metallurgy', 'Explain ore concentration, conversion, reduction, aluminium extraction and common alloys.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-metallurgy', 'topic-x-chem-metallurgy', 'Metallurgy', 'Metallurgy extracts metals economically from ores. A mineral is a naturally occurring substance containing a metal or its compound; an ore is a mineral from which extraction is practical and economical. Ore is crushed and concentrated by methods such as hydraulic washing, magnetic separation or froth flotation. Sulphide ores are commonly roasted in air, while carbonates and hydrated ores are calcined with limited or no air to form oxides. Moderately reactive metal oxides may be reduced by carbon, carbon monoxide or hydrogen, but highly reactive metals require electrolysis. Aluminium is obtained from purified bauxite: Bayer’s process removes impurities, and the Hall–Héroult process electrolyses alumina dissolved in molten cryolite, which lowers operating temperature and improves conductivity. Carbon anodes are consumed by oxygen formed at the anode. Refining improves purity. Alloys combine useful properties; examples include brass, bronze, stainless steel, duralumin, magnalium and solder, each with a specified composition and use.', '["An ore is a mineral from which a metal can be extracted conveniently and economically.","Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air.","Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically.","Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."]', '{"prompt":"Why is aluminium oxide not reduced with carbon, and what method is used instead?","steps":["Aluminium is above carbon in the activity series and its oxide is very stable.","Carbon cannot remove oxygen from Al₂O₃ under ordinary extraction conditions.","Alumina dissolved in molten cryolite is therefore electrolysed in the Hall–Héroult process."],"answer":"Electrolytic reduction of alumina in molten cryolite."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-metallurgy-q1', 'topic-x-chem-metallurgy', 'single_choice', 'Which statement correctly describes Metallurgy?', '[{"id":"a","label":"An ore is a mineral from which a metal can be extracted conveniently and economically."},{"id":"b","label":"The first portion is discarded to remove air; pure hydrogen burns with a pale blue flame and gives a pop with a lighted splint."},{"id":"c","label":"Hydrogen reduces heated copper(II) oxide to copper and is itself oxidised to water."},{"id":"d","label":"Hydrogen is used in ammonia manufacture, oil hydrogenation, high-temperature flames and fuel cells."}]', '{"choice":"a"}', 'An ore is a mineral from which a metal can be extracted conveniently and economically.', 1, 0, 'reviewed', 1),
('x-chem-metallurgy-q2', 'topic-x-chem-metallurgy', 'single_choice', 'Which statement correctly describes Metallurgy?', '[{"id":"a","label":"Solubility is measured at a stated temperature, and a saturated solution cannot dissolve more solute under those conditions."},{"id":"b","label":"Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air."},{"id":"c","label":"Most solid solutes become more soluble on heating, while gases usually become less soluble."},{"id":"d","label":"Temporary hardness can be removed by boiling; permanent hardness requires methods such as washing soda, ion exchange or distillation."}]', '{"choice":"b"}', 'Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air.', 2, 0, 'reviewed', 1),
('x-chem-metallurgy-q3', 'topic-x-chem-metallurgy', 'single_choice', 'Which statement correctly describes Metallurgy?', '[{"id":"a","label":"Purification methods remove different hazards: filtration removes suspended solids, while boiling or disinfection controls microorganisms."},{"id":"b","label":"Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings."},{"id":"c","label":"Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically."},{"id":"d","label":"Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another."}]', '{"choice":"c"}', 'Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically.', 3, 0, 'reviewed', 1),
('x-chem-metallurgy-q4', 'topic-x-chem-metallurgy', 'single_choice', 'Which statement correctly describes Metallurgy?', '[{"id":"a","label":"Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide."},{"id":"b","label":"Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."},{"id":"c","label":"Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements."},{"id":"d","label":"Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."}]', '{"choice":"d"}', 'Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell.', 4, 0, 'reviewed', 1),
('x-chem-metallurgy-q5', 'topic-x-chem-metallurgy', 'single_choice', 'Why is aluminium oxide not reduced with carbon, and what method is used instead? Which conclusion is correct?', '[{"id":"a","label":"It is very soluble; acidity requires water for ionisation."},{"id":"b","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"c","label":"To limit decomposition and obtain purer nitric acid."},{"id":"d","label":"Electrolytic reduction of alumina in molten cryolite."}]', '{"choice":"d"}', 'Aluminium is above carbon in the activity series and its oxide is very stable. Carbon cannot remove oxygen from Al₂O₃ under ordinary extraction conditions. Alumina dissolved in molten cryolite is therefore electrolysed in the Hall–Héroult process.', 2, 1, 'reviewed', 1);
INSERT INTO assignment_templates
  (id, module_id, class_level, subject, title, instructions, estimated_minutes, review_status, active, version, sequence)
