VALUES
('topic-x-chem-hydrogen-chloride', 'CISCE', 2027, 'X', 'Chemistry', 'Study of Compounds', 'Hydrogen Chloride', 'Describe preparation, collection, solubility, acidic reactions, tests and uses of hydrogen chloride.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-hydrogen-chloride', 'topic-x-chem-hydrogen-chloride', 'Hydrogen Chloride', 'Hydrogen chloride gas is prepared in the laboratory by warming sodium chloride with concentrated sulphuric acid. Because it is highly soluble in water and denser than air, it is collected by downward displacement of air rather than over water. Dry HCl does not affect dry blue litmus because ions are not formed without water; dissolved HCl forms hydronium and chloride ions and shows strong acidic properties. Its exceptional solubility is demonstrated by the fountain experiment. Hydrogen chloride reacts with ammonia to form dense white fumes of ammonium chloride. Hydrochloric acid reacts with suitable metals, metal oxides, hydroxides and carbonates to form chlorides. Chloride ions produce a white precipitate of silver chloride with silver nitrate after appropriate acidification; the precipitate dissolves in ammonium hydroxide. Aqua regia is one volume concentrated nitric acid with three volumes concentrated hydrochloric acid and dissolves noble metals such as gold.', '["HCl gas is highly soluble in water, denser than air and collected by downward displacement of air.","Dry HCl is not acidic to dry litmus; water enables ionisation to H₃O⁺ and Cl⁻.","HCl and NH₃ form dense white fumes of NH₄Cl.","Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide."]', '{"prompt":"Explain why hydrogen chloride cannot be collected over water and why dry HCl does not redden dry blue litmus.","steps":["HCl dissolves extremely readily in water, so water collection would absorb the gas.","Acid behaviour requires hydronium ions formed when HCl ionises in water.","With no water on dry litmus, ionisation does not occur and the colour remains unchanged."],"answer":"It is very soluble; acidity requires water for ionisation."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-hydrogen-chloride-q1', 'topic-x-chem-hydrogen-chloride', 'single_choice', 'Which statement correctly describes Hydrogen Chloride?', '[{"id":"a","label":"HCl gas is highly soluble in water, denser than air and collected by downward displacement of air."},{"id":"b","label":"Carbon is tetravalent and shows catenation, allowing stable chains, branches and rings."},{"id":"c","label":"Diamond is a hard three-dimensional covalent network; graphite has conducting layers that slide over one another."},{"id":"d","label":"Complete combustion forms carbon dioxide, while incomplete combustion may form highly poisonous carbon monoxide."}]', '{"choice":"a"}', 'HCl gas is highly soluble in water, denser than air and collected by downward displacement of air.', 1, 0, 'reviewed', 1),
('x-chem-hydrogen-chloride-q2', 'topic-x-chem-hydrogen-chloride', 'single_choice', 'Which statement correctly describes Hydrogen Chloride?', '[{"id":"a","label":"Carbon dioxide supports photosynthesis and contributes to warming in excess; activated charcoal adsorbs substances on its porous surface."},{"id":"b","label":"Dry HCl is not acidic to dry litmus; water enables ionisation to H₃O⁺ and Cl⁻."},{"id":"c","label":"Modern periodic law relates recurring properties to atomic number, and group similarity arises from related valence-electron arrangements."},{"id":"d","label":"Across a period atomic size and metallic character generally decrease, while ionisation potential and electronegativity generally increase."}]', '{"choice":"b"}', 'Dry HCl is not acidic to dry litmus; water enables ionisation to H₃O⁺ and Cl⁻.', 2, 0, 'reviewed', 1),
('x-chem-hydrogen-chloride-q3', 'topic-x-chem-hydrogen-chloride', 'single_choice', 'Which statement correctly describes Hydrogen Chloride?', '[{"id":"a","label":"Down a group atomic size and metallic character generally increase because new shells and shielding reduce nuclear attraction on valence electrons."},{"id":"b","label":"Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."},{"id":"c","label":"HCl and NH₃ form dense white fumes of NH₄Cl."},{"id":"d","label":"Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice."}]', '{"choice":"c"}', 'HCl and NH₃ form dense white fumes of NH₄Cl.', 3, 0, 'reviewed', 1),
('x-chem-hydrogen-chloride-q4', 'topic-x-chem-hydrogen-chloride', 'single_choice', 'Which statement correctly describes Hydrogen Chloride?', '[{"id":"a","label":"Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed."},{"id":"b","label":"Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules."},{"id":"c","label":"In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."},{"id":"d","label":"Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide."}]', '{"choice":"d"}', 'Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide.', 4, 0, 'reviewed', 1),
('x-chem-hydrogen-chloride-q5', 'topic-x-chem-hydrogen-chloride', 'single_choice', 'Explain why hydrogen chloride cannot be collected over water and why dry HCl does not redden dry blue litmus. Which conclusion is correct?', '[{"id":"a","label":"It is very soluble; acidity requires water for ionisation."},{"id":"b","label":"35.0 g"},{"id":"c","label":"Melting is physical; burning is chemical."},{"id":"d","label":"Magnetic separation, then sublimation, leaving sand."}]', '{"choice":"a"}', 'HCl dissolves extremely readily in water, so water collection would absorb the gas. Acid behaviour requires hydronium ions formed when HCl ionises in water. With no water on dry litmus, ionisation does not occur and the colour remains unchanged.', 2, 1, 'reviewed', 1);
