VALUES
('topic-x-chem-ammonia', 'CISCE', 2027, 'X', 'Chemistry', 'Study of Compounds', 'Ammonia', 'Explain preparation, Haber manufacture, properties, reactions, tests and uses of ammonia.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-ammonia', 'topic-x-chem-ammonia', 'Ammonia', 'Ammonia is prepared in the laboratory by heating an ammonium salt such as ammonium chloride with calcium hydroxide. It is dried with quicklime because common acidic drying agents react with it. Ammonia is extremely soluble in water and lighter than air, so it is collected by downward displacement of air and not over water. Its fountain experiment demonstrates high solubility; aqueous ammonia is weakly alkaline because only some molecules form ammonium and hydroxide ions. The Haber process combines nitrogen and hydrogen reversibly using an iron catalyst at elevated temperature and pressure, with product removal improving yield. Ammonia forms white fumes with hydrogen chloride, reduces hot copper(II) oxide, burns in oxygen and is catalytically oxidised to nitric oxide in nitric acid manufacture. With chlorine, products depend on which reactant is in excess. Uses include fertilisers, nitric acid, explosives, refrigerants and cleaning solutions. A pungent smell, red-litmus-to-blue change and white HCl fumes identify it.', '["Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime.","Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution.","The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature.","Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper."]', '{"prompt":"Write the balanced laboratory preparation equation for ammonia from ammonium chloride and calcium hydroxide.","steps":["Identify products: calcium chloride, ammonia and water.","Start with 2NH₄Cl to supply two ammonium ions and match CaCl₂.","Balance hydrogen and oxygen: 2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."],"answer":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-ammonia-q1', 'topic-x-chem-ammonia', 'single_choice', 'Which statement correctly describes Ammonia?', '[{"id":"a","label":"Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime."},{"id":"b","label":"Alkali metals become more reactive down Group 1, whereas halogens generally become less reactive down Group 17."},{"id":"c","label":"Ionic bonding transfers electrons and produces oppositely charged ions held in a lattice."},{"id":"d","label":"Ionic compounds conduct when molten or aqueous because ions are mobile, but not as solids where ions are fixed."}]', '{"choice":"a"}', 'Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime.', 1, 0, 'reviewed', 1),
('x-chem-ammonia-q2', 'topic-x-chem-ammonia', 'single_choice', 'Which statement correctly describes Ammonia?', '[{"id":"a","label":"Covalent bonding shares electron pairs; unequal sharing creates polar covalent molecules."},{"id":"b","label":"Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution."},{"id":"c","label":"In a coordinate bond both electrons in the shared pair are donated by one atom, as in NH₄⁺ and H₃O⁺."},{"id":"d","label":"Acids produce H₃O⁺ in water and alkalis produce OH⁻; indicators and pH reveal the resulting solution conditions."}]', '{"choice":"b"}', 'Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution.', 2, 0, 'reviewed', 1),
('x-chem-ammonia-q3', 'topic-x-chem-ammonia', 'single_choice', 'Which statement correctly describes Ammonia?', '[{"id":"a","label":"A salt results from partial or complete replacement of ionisable hydrogen in an acid by a metal or ammonium ion."},{"id":"b","label":"Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions."},{"id":"c","label":"The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature."},{"id":"d","label":"Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."}]', '{"choice":"c"}', 'The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature.', 3, 0, 'reviewed', 1),
('x-chem-ammonia-q4', 'topic-x-chem-ammonia', 'single_choice', 'Which statement correctly describes Ammonia?', '[{"id":"a","label":"Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃."},{"id":"b","label":"Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide."},{"id":"c","label":"Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH."},{"id":"d","label":"Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper."}]', '{"choice":"d"}', 'Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper.', 4, 0, 'reviewed', 1),
('x-chem-ammonia-q5', 'topic-x-chem-ammonia', 'single_choice', 'Write the balanced laboratory preparation equation for ammonia from ammonium chloride and calcium hydroxide. Which conclusion is correct?', '[{"id":"a","label":"A displacement reaction: Zn + CuSO₄ → ZnSO₄ + Cu."},{"id":"b","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"c","label":"Zn + 2HCl → ZnCl₂ + H₂; discard the first gas."},{"id":"d","label":"162.5 g"}]', '{"choice":"b"}', 'Identify products: calcium chloride, ammonia and water. Start with 2NH₄Cl to supply two ammonium ions and match CaCl₂. Balance hydrogen and oxygen: 2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O.', 2, 1, 'reviewed', 1);
