INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-nitric-acid', 'CISCE', 2027, 'X', 'Chemistry', 'Study of Compounds', 'Nitric Acid', 'Describe preparation, Ostwald manufacture, oxidising reactions, tests and uses of nitric acid.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-nitric-acid', 'topic-x-chem-nitric-acid', 'Nitric Acid', 'Nitric acid is prepared in the laboratory by heating an alkali-metal nitrate with concentrated sulphuric acid below about 200 °C and condensing the volatile acid. Industrially, the Ostwald process catalytically oxidises ammonia to nitric oxide over platinum–rhodium gauze; further oxidation gives nitrogen dioxide, which is absorbed in water with oxygen to form nitric acid. Pure nitric acid is colourless but may appear yellow because dissolved nitrogen dioxide forms on decomposition. It is a strong acid and a powerful oxidising agent. Most metals do not liberate hydrogen from nitric acid because the acid oxidises the hydrogen and is reduced to nitrogen oxides; product depends on concentration and metal. Concentrated nitric acid passivates iron and aluminium at ordinary temperature by forming a protective oxide film. It oxidises carbon and sulphur and forms nitrates with bases and carbonates. Nitrate identification uses the brown-ring test under controlled laboratory conditions. Uses include fertilisers, explosives, dyes and chemical manufacture.', '["Laboratory HNO₃ is displaced from a nitrate by concentrated H₂SO₄ and collected by condensation.","The Ostwald process oxidises NH₃ to NO, then NO₂, followed by absorption to form nitric acid.","Nitric acid usually does not release H₂ from metals because it is a strong oxidising agent.","Concentrated nitric acid passivates iron and aluminium by forming a protective oxide layer."]', '{"prompt":"Why is the apparatus kept below about 200 °C when preparing nitric acid from sodium nitrate and concentrated sulphuric acid?","steps":["Moderate heating distils nitric acid from the reaction mixture.","At excessive temperature nitric acid decomposes and contaminating nitrogen dioxide forms.","Keeping the temperature controlled improves purity and safe collection by condensation."],"answer":"To limit decomposition and obtain purer nitric acid."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-nitric-acid-q1', 'topic-x-chem-nitric-acid', 'single_choice', 'Which statement correctly describes Nitric Acid?', '[{"id":"a","label":"Laboratory HNO₃ is displaced from a nitrate by concentrated H₂SO₄ and collected by condensation."},{"id":"b","label":"Insoluble salts are commonly prepared by precipitation; soluble salts may use neutralisation, titration or acid reactions."},{"id":"c","label":"Acid plus carbonate gives salt, water and carbon dioxide, while acid plus sulphite releases sulphur dioxide."},{"id":"d","label":"Fe²⁺ gives dirty green Fe(OH)₂ that oxidises brown; Fe³⁺ gives reddish-brown Fe(OH)₃."}]', '{"choice":"a"}', 'Laboratory HNO₃ is displaced from a nitrate by concentrated H₂SO₄ and collected by condensation.', 1, 0, 'reviewed', 1),
('x-chem-nitric-acid-q2', 'topic-x-chem-nitric-acid', 'single_choice', 'Which statement correctly describes Nitric Acid?', '[{"id":"a","label":"Cu²⁺ gives light blue Cu(OH)₂ and a deep blue solution in excess ammonium hydroxide."},{"id":"b","label":"The Ostwald process oxidises NH₃ to NO, then NO₂, followed by absorption to form nitric acid."},{"id":"c","label":"Zn²⁺ gives a white precipitate soluble in excess NaOH and excess NH₄OH."},{"id":"d","label":"Pb²⁺ gives a white precipitate soluble in excess NaOH but insoluble in excess NH₄OH."}]', '{"choice":"b"}', 'The Ostwald process oxidises NH₃ to NO, then NO₂, followed by absorption to form nitric acid.', 2, 0, 'reviewed', 1),
('x-chem-nitric-acid-q3', 'topic-x-chem-nitric-acid', 'single_choice', 'Which statement correctly describes Nitric Acid?', '[{"id":"a","label":"One mole contains 6.022 × 10²³ entities and has mass equal to the relative atomic or molecular mass expressed in grams."},{"id":"b","label":"At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus."},{"id":"c","label":"Nitric acid usually does not release H₂ from metals because it is a strong oxidising agent."},{"id":"d","label":"A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers."}]', '{"choice":"c"}', 'Nitric acid usually does not release H₂ from metals because it is a strong oxidising agent.', 3, 0, 'reviewed', 1),
('x-chem-nitric-acid-q4', 'topic-x-chem-nitric-acid', 'single_choice', 'Which statement correctly describes Nitric Acid?', '[{"id":"a","label":"Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."},{"id":"b","label":"Cations move to the cathode and gain electrons; anions move to the anode and lose electrons."},{"id":"c","label":"Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active."},{"id":"d","label":"Concentrated nitric acid passivates iron and aluminium by forming a protective oxide layer."}]', '{"choice":"d"}', 'Concentrated nitric acid passivates iron and aluminium by forming a protective oxide layer.', 4, 0, 'reviewed', 1),
('x-chem-nitric-acid-q5', 'topic-x-chem-nitric-acid', 'single_choice', 'Why is the apparatus kept below about 200 °C when preparing nitric acid from sodium nitrate and concentrated sulphuric acid? Which conclusion is correct?', '[{"id":"a","label":"Ions are fixed in the solid but mobile in the melt."},{"id":"b","label":"Precipitation, followed by filtration, washing and drying."},{"id":"c","label":"To limit decomposition and obtain purer nitric acid."},{"id":"d","label":"Pb²⁺ (lead(II))."}]', '{"choice":"c"}', 'Moderate heating distils nitric acid from the reaction mixture. At excessive temperature nitric acid decomposes and contaminating nitrogen dioxide forms. Keeping the temperature controlled improves purity and safe collection by condensation.', 2, 1, 'reviewed', 1);
