INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
('topic-x-chem-sulphuric-acid', 'CISCE', 2027, 'X', 'Chemistry', 'Study of Compounds', 'Sulphuric Acid', 'Explain Contact manufacture and distinguish dilute-acid, oxidising, dehydrating and non-volatile behaviour.', 'https://cisce.org/wp-content/uploads/2025/03/11.-Chemistry.pdf', '2026-10-22', 'reviewed', 1);
INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-sulphuric-acid', 'topic-x-chem-sulphuric-acid', 'Sulphuric Acid', 'Sulphuric acid is manufactured by the Contact process. Sulphur dioxide is purified, mixed with air and reversibly oxidised to sulphur trioxide over vanadium(V) oxide at a compromise temperature. Sulphur trioxide is absorbed in concentrated sulphuric acid to form oleum, which is diluted safely to the desired acid concentration. Direct absorption in water is avoided because a corrosive acid mist forms. Dilute sulphuric acid behaves as a strong dibasic acid, reacting with suitable metals, bases, carbonates, hydrogencarbonates, sulphites and sulphides. Concentrated sulphuric acid is also an oxidising agent, converting carbon or sulphur to oxides while being reduced to sulphur dioxide. It is a powerful dehydrating agent, charring sugar and removing water from hydrated copper(II) sulphate, and its low volatility allows it to displace more volatile acids from salts. Sulphate ions produce a white barium sulphate precipitate with barium chloride after acidification.', '["The Contact process uses V₂O₅ to catalyse 2SO₂ + O₂ ⇌ 2SO₃ under compromise conditions.","SO₃ is absorbed in concentrated H₂SO₄ to form oleum before dilution, avoiding acid mist.","Dilute H₂SO₄ shows ordinary acidic reactions; concentrated acid can oxidise and dehydrate.","Sulphate ions give a white insoluble BaSO₄ precipitate with a soluble barium salt after acidification."]', '{"prompt":"Explain why sulphur trioxide is not absorbed directly in water during the Contact process.","steps":["The reaction of SO₃ with water is extremely exothermic.","Direct contact produces a fine mist of sulphuric acid that is difficult to condense and hazardous.","SO₃ is first absorbed in concentrated acid to make oleum, which is then diluted."],"answer":"Direct absorption forms acid mist; use oleum then dilute."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-sulphuric-acid-q1', 'topic-x-chem-sulphuric-acid', 'single_choice', 'Which statement correctly describes Sulphuric Acid?', '[{"id":"a","label":"The Contact process uses V₂O₅ to catalyse 2SO₂ + O₂ ⇌ 2SO₃ under compromise conditions."},{"id":"b","label":"At STP, one mole of gas occupies 22.4 L under the convention used in this syllabus."},{"id":"c","label":"A balanced equation gives mole ratios that connect reactant and product masses, volumes and particle numbers."},{"id":"d","label":"Empirical formula is the simplest ratio; molecular formula is an integer multiple fixed by molar mass."}]', '{"choice":"a"}', 'The Contact process uses V₂O₅ to catalyse 2SO₂ + O₂ ⇌ 2SO₃ under compromise conditions.', 1, 0, 'reviewed', 1),
('x-chem-sulphuric-acid-q2', 'topic-x-chem-sulphuric-acid', 'single_choice', 'Which statement correctly describes Sulphuric Acid?', '[{"id":"a","label":"Cations move to the cathode and gain electrons; anions move to the anode and lose electrons."},{"id":"b","label":"SO₃ is absorbed in concentrated H₂SO₄ to form oleum before dilution, avoiding acid mist."},{"id":"c","label":"Selective discharge depends on ion position in the activity series, concentration and whether electrodes are inert or active."},{"id":"d","label":"Molten lead bromide produces Pb at the cathode and Br₂ at the anode."}]', '{"choice":"b"}', 'SO₃ is absorbed in concentrated H₂SO₄ to form oleum before dilution, avoiding acid mist.', 2, 0, 'reviewed', 1),
('x-chem-sulphuric-acid-q3', 'topic-x-chem-sulphuric-acid', 'single_choice', 'Which statement correctly describes Sulphuric Acid?', '[{"id":"a","label":"In electroplating the article is cathode, the coating metal is generally anode and a soluble salt supplies metal ions."},{"id":"b","label":"An ore is a mineral from which a metal can be extracted conveniently and economically."},{"id":"c","label":"Dilute H₂SO₄ shows ordinary acidic reactions; concentrated acid can oxidise and dehydrate."},{"id":"d","label":"Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air."}]', '{"choice":"c"}', 'Dilute H₂SO₄ shows ordinary acidic reactions; concentrated acid can oxidise and dehydrate.', 3, 0, 'reviewed', 1),
('x-chem-sulphuric-acid-q4', 'topic-x-chem-sulphuric-acid', 'single_choice', 'Which statement correctly describes Sulphuric Acid?', '[{"id":"a","label":"Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically."},{"id":"b","label":"Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."},{"id":"c","label":"HCl gas is highly soluble in water, denser than air and collected by downward displacement of air."},{"id":"d","label":"Sulphate ions give a white insoluble BaSO₄ precipitate with a soluble barium salt after acidification."}]', '{"choice":"d"}', 'Sulphate ions give a white insoluble BaSO₄ precipitate with a soluble barium salt after acidification.', 4, 0, 'reviewed', 1),
('x-chem-sulphuric-acid-q5', 'topic-x-chem-sulphuric-acid', 'single_choice', 'Explain why sulphur trioxide is not absorbed directly in water during the Contact process. Which conclusion is correct?', '[{"id":"a","label":"Electrolytic reduction of alumina in molten cryolite."},{"id":"b","label":"It is very soluble; acidity requires water for ionisation."},{"id":"c","label":"2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2NH₃ + 2H₂O."},{"id":"d","label":"Direct absorption forms acid mist; use oleum then dilute."}]', '{"choice":"d"}', 'The reaction of SO₃ with water is extremely exothermic. Direct contact produces a fine mist of sulphuric acid that is difficult to condense and hazardous. SO₃ is first absorbed in concentrated acid to make oleum, which is then diluted.', 2, 1, 'reviewed', 1);
