INSERT INTO curriculum_topic_sources (topic_id, source_id, relationship)
INSERT INTO learning_modules
  (id, topic_id, title, overview, key_points_json, worked_example_json, practice_advice, review_status, version)
VALUES
('module-x-chem-organic-chemistry', 'topic-x-chem-organic-chemistry', 'Organic Chemistry', 'Organic chemistry studies carbon compounds, whose diversity follows from tetravalency and catenation. A homologous series has the same functional group and general formula, similar chemical properties and successive members differing by CH₂. Alkanes are saturated hydrocarbons with single bonds; alkenes and alkynes are unsaturated and contain double or triple bonds. Structural formulae reveal connectivity, and IUPAC names identify the longest chain, bond type, substituent positions and functional group. Chain isomerism occurs when compounds share a molecular formula but differ in carbon skeleton. Methane undergoes combustion and substitution with chlorine in light. Ethene and ethyne undergo addition reactions and decolourise bromine solution; ethene can polymerise. Ethanol burns, reacts with sodium and can be oxidised to ethanoic acid. Ethanoic acid shows acidic reactions and reacts with ethanol in the presence of concentrated sulphuric acid to form a sweet-smelling ester. Equations require correct conditions and balanced atoms.', '["A homologous series shares a functional group and general formula; adjacent members differ by CH₂.","Alkanes are saturated, while alkenes and alkynes are unsaturated and undergo addition reactions.","Compounds can share a molecular formula but have different structural arrangements called isomers.","Ethanol oxidises to ethanoic acid, and ethanol plus ethanoic acid forms an ester and water."]', '{"prompt":"Name CH₃CH₂CH₂OH and state the product when it is oxidised under controlled conditions.","steps":["The longest chain has three carbon atoms, giving the root propan-.","The terminal –OH group gives the suffix -1-ol, so the name is propan-1-ol.","Oxidation of a primary alcohol gives the corresponding carboxylic acid: propanoic acid."],"answer":"Propan-1-ol; oxidation gives propanoic acid."}', 'Read each equation or observation aloud, identify the governing idea before choosing an answer, and check that atoms, charge, conditions and units are consistent.', 'reviewed', 1);
INSERT INTO questions
  (id, topic_id, question_type, prompt, options_json, answer_json, rationale, difficulty, requires_rough_work, review_status, version)
VALUES
('x-chem-organic-chemistry-q1', 'topic-x-chem-organic-chemistry', 'single_choice', 'Which statement correctly describes Organic Chemistry?', '[{"id":"a","label":"A homologous series shares a functional group and general formula; adjacent members differ by CH₂."},{"id":"b","label":"An ore is a mineral from which a metal can be extracted conveniently and economically."},{"id":"c","label":"Roasting heats sulphide ore in excess air; calcination heats carbonate or hydrated ore with little or no air."},{"id":"d","label":"Highly reactive metals such as aluminium cannot be reduced by carbon and are extracted electrolytically."}]', '{"choice":"a"}', 'A homologous series shares a functional group and general formula; adjacent members differ by CH₂.', 1, 0, 'reviewed', 1),
('x-chem-organic-chemistry-q2', 'topic-x-chem-organic-chemistry', 'single_choice', 'Which statement correctly describes Organic Chemistry?', '[{"id":"a","label":"Cryolite lowers the melting point of alumina and improves conductivity in the Hall–Héroult cell."},{"id":"b","label":"Alkanes are saturated, while alkenes and alkynes are unsaturated and undergo addition reactions."},{"id":"c","label":"HCl gas is highly soluble in water, denser than air and collected by downward displacement of air."},{"id":"d","label":"Dry HCl is not acidic to dry litmus; water enables ionisation to H₃O⁺ and Cl⁻."}]', '{"choice":"b"}', 'Alkanes are saturated, while alkenes and alkynes are unsaturated and undergo addition reactions.', 2, 0, 'reviewed', 1),
('x-chem-organic-chemistry-q3', 'topic-x-chem-organic-chemistry', 'single_choice', 'Which statement correctly describes Organic Chemistry?', '[{"id":"a","label":"HCl and NH₃ form dense white fumes of NH₄Cl."},{"id":"b","label":"Chloride ions give white AgCl with AgNO₃, and AgCl dissolves in ammonium hydroxide."},{"id":"c","label":"Compounds can share a molecular formula but have different structural arrangements called isomers."},{"id":"d","label":"Laboratory ammonia is made by heating an ammonium salt with a strong base and is dried with quicklime."}]', '{"choice":"c"}', 'Compounds can share a molecular formula but have different structural arrangements called isomers.', 3, 0, 'reviewed', 1),
('x-chem-organic-chemistry-q4', 'topic-x-chem-organic-chemistry', 'single_choice', 'Which statement correctly describes Organic Chemistry?', '[{"id":"a","label":"Ammonia is lighter than air, highly soluble in water and weakly alkaline in aqueous solution."},{"id":"b","label":"The Haber process uses nitrogen and hydrogen, an iron catalyst, raised pressure and a compromise temperature."},{"id":"c","label":"Ammonia gives dense white NH₄Cl fumes with HCl and reduces hot CuO to copper."},{"id":"d","label":"Ethanol oxidises to ethanoic acid, and ethanol plus ethanoic acid forms an ester and water."}]', '{"choice":"d"}', 'Ethanol oxidises to ethanoic acid, and ethanol plus ethanoic acid forms an ester and water.', 4, 0, 'reviewed', 1),
('x-chem-organic-chemistry-q5', 'topic-x-chem-organic-chemistry', 'single_choice', 'Name CH₃CH₂CH₂OH and state the product when it is oxidised under controlled conditions. Which conclusion is correct?', '[{"id":"a","label":"Propan-1-ol; oxidation gives propanoic acid."},{"id":"b","label":"35.0 g"},{"id":"c","label":"Melting is physical; burning is chemical."},{"id":"d","label":"Magnetic separation, then sublimation, leaving sand."}]', '{"choice":"a"}', 'The longest chain has three carbon atoms, giving the root propan-. The terminal –OH group gives the suffix -1-ol, so the name is propan-1-ol. Oxidation of a primary alcohol gives the corresponding carboxylic acid: propanoic acid.', 2, 1, 'reviewed', 1);
